func NormalizeKind(kind string) string {
	return strings.ToLower(strings.TrimSpace(kind))
}

arguments.body:
event.Kind = audit.NormalizeKind(event.Kind)
	if event.Kind == "probe" {
		return nil
	}
	return d.sink.Write(event)

for _, event := range events {
		event.Kind = audit.NormalizeKind(event.Kind)
		if event.Kind == "probe" {
			continue
		}
		if err := sink.Write(event); err != nil {
			return err
		}
	}
	return nil

for _, event := range events {
		event.Kind = audit.NormalizeKind(event.Kind)
		if event.Kind == "probe" {
			continue
		}
		if err := sink.Write(event); err != nil {
			return err
		}
	}
	return nil

for _, event := range b.queue {
		event.Kind = NormalizeKind(event.Kind)
		if event.Kind == "probe" {
			continue
		}
		if err := b.Sink.Write(event); err != nil {
			return err
		}
	}
	return nil

event.Kind = NormalizeKind(event.Kind)
	if event.Kind == "probe" {
		return nil
	}
	if err := f.First.Write(event); err != nil {
		return err
	}
	return f.Second.Write(event)

switch NormalizeKind(kind) {
	case "health", "probe":
		return "control"
	default:
		return "data"
	}

