func NormalizeEvent(event Event) (Event, bool) {
	event.Kind = strings.ToLower(strings.TrimSpace(event.Kind))
	return event, event.Kind != "probe"
}

func Deliver(sink Sink, event Event) error {
	normalized, persist := NormalizeEvent(event)
	if !persist {
		return nil
	}
	return sink.Write(normalized)
}

